"""
    Applies the predicate to each item, taking the disjunction of the results.
    Will add d as a disjunct, and then finally will take that in
    conjunction with c. Returns the value.
    """
def build_mask(items: Any, predicate: Any, d: Any = None, c: Any = None) -> object {
    q = None;
    for i in items {
        if (q is None) {
            q = predicate(i);
        } else {
            q |= predicate(i);
        }
    }
    if (d is not None) {
        q = d | q;
    }
    if (c is not None) {
        q = c & q;
    }
    return q;
}

