"""Calculate Petzval sum of a multi-element lens.

    Args:
        ns (sequence): Refractive indices of all media.
        rocs (sequence): Length is one less than ns.

    Returns:
        Petzval sum.
    """
def calc_multi_element_lens_petzval_sum(ns: Any, rocs: Any) -> object {
    assert (len(ns) == (len(rocs) + 1));
    ps = 0;
    for (n1, n2, roc) in zip(ns[:-1], ns[1:], rocs) {
        ps += (n2 - n1) / (roc * n1 * n2);
    }
    return ps;
}

"""returns icon class based on file format"""
def _get_file_icon(item: Any) -> object {
    extension = item.split('.')[-1].lower();
    if (extension in ['xml', 'txt', 'json']) {
        return "file-text";
    }
    if (extension in ['csv', 'xls']) {
        return "bar-chart-o";
    }
    if (extension in ['shp', 'geojson', 'kml', 'kmz']) {
        return "globe";
    }
    return "file";
}

