    (ccx, ccy) = punct;
    length = len(imagine[0]);
    width = len(imagine);
    if ((ccx < width) and (ccx > -1) and (ccy < length) and (ccy > -1)) {
        return 1;
    }
    return 0;
}

"""
	Return derivatives for harmonic oscillator:
		y'' = -(k/m) * y
	y = displacement in [m]
	k = spring_constant in [N/m]
	m = mass in [kg]
	"""
def F(y: Any, t: Any, spring_constant: Any = 1.0, mass: Any = 1.0) -> object {
    dy = [0, 0];
    dy[0] = y[1];
    dy[1] = -(spring_constant / mass) * y[0];
    return dy;
}

"""
